// Author: MiYu. Original passenger portraits and live cargo capacity share native unload commands in the information panel.
#include "game_view.h"
#include <algorithm>
#include <bit>

namespace war3 {
namespace {float number(jass::Real value){return std::bit_cast<float>(value.bits());}bool hit(float x,float y,float left,float top,float width,float height){return x>=left && y>=top && x<=left+width && y<=top+height;}}
void GameView::cargoPanel(const GameInput& input,std::uint32_t id){
    auto& session=*data_->session;if(!session.units().contains(id))return;auto u=session.units().at(id);auto capacity=session.cargoCapacity(id);if(!capacity || u->owner!=session.localPlayer().value_or(0))return;if(cargoPanelUnit_!=id){cargoPanelUnit_=id;cargoPage_=0;}auto pages=(capacity+11)/12;cargoPage_=std::min(cargoPage_,pages-1);float scale=std::min(renderer_.width()/.8f,renderer_.height()/.6f),left=(renderer_.width()-.8f*scale)/2,top=(renderer_.height()-.6f*scale)/2;auto quad=[&](float x,float y,float w,float h,DWORD color,IDirect3DTexture9* image=nullptr){renderer_.rect(left+x*scale,top+y*scale,w*scale,h*scale,color,image);};auto label=[&](const std::wstring& text,float x,float y,float height,DWORD color=0xffffffff){text_.draw(text,left+x*scale,top+y*scale,height*scale,color);};bool corpses=session.corpseCarrier(id);label((corpses?L"尸体 ":L"")+std::to_wstring(session.cargoUsed(id))+L" / "+std::to_wstring(capacity),.463f,.49f,.011f);
    unsigned first=cargoPage_*12;for(unsigned i=0;i<12 && first+i<capacity;++i)quad(.27f+(i%6)*.031f,.528f+(i/6)*.033f,.027f,.027f,0xff171717);auto manifest=u->cargo;unsigned slot=0;for(auto passengerId:manifest){if(!session.units().contains(passengerId))continue;auto passenger=session.units().at(passengerId);if(passenger->transport!=id)continue;auto size=session.cargoCost(passengerId);unsigned index=slot;slot+=size;if(index<first || index>=first+12)continue;index-=first;float x=.27f+(index%6)*.031f,y=.528f+(index/6)*.033f;if(auto icon=data_->assets->cachedTexture(passenger->displayIcon()))quad(x,y,.027f,.027f,0xffffffff,icon);if(!corpses){quad(x,y+.026f,.027f,.002f,0xff222222);quad(x,y+.026f,.027f*std::clamp(number(passenger->life)/std::max(1.f,number(passenger->maxLife)),0.f,1.f),.002f,0xff33bb33);}if(size>1)label(std::to_wstring(size),x+.018f,y+.016f,.009f);if(hit(input.ui.x,input.ui.y,x,y,.027f,.027f)){label(wide(passenger->name),.27f,.51f,.011f,0xffffcc55);if(input.ui.pressed && !passenger->digestion){if(!session.unloadUnit(id,passengerId))session.displayText(u->owner,0,0,2,"当前无法卸载该乘员");else{spellTarget_.reset();buildTarget_.reset();itemTarget_.reset();orderMode_=OrderMode::None;skillMenuUnit_=0;buildMenuUnit_=0;}return;}}}
    if(pages>1){label(L"<",.465f,.551f,.014f);label(L">",.49f,.551f,.014f);label(std::to_wstring(cargoPage_+1)+L" / "+std::to_wstring(pages),.463f,.575f,.009f);if(input.ui.pressed){if(hit(input.ui.x,input.ui.y,.463f,.548f,.02f,.023f) && cargoPage_)--cargoPage_;else if(hit(input.ui.x,input.ui.y,.488f,.548f,.02f,.023f) && cargoPage_+1<pages)++cargoPage_;}}
}
}
